import numpy as np
key=np.array([[0,4,0],[0,4,2],[3,0,2]])
mask=np.array([[1,0,0],[0,1,1],[1,1,0]])
for k in range(4):
 a=np.rot90(key,k)
 print('k',k,a, 'occ match',np.array_equal(a!=0,mask),sep='\n')
print('flips')
for a0 in [key,np.fliplr(key),np.flipud(key),key.T]:
 for k in range(4):
  a=np.rot90(a0,k)
  if np.array_equal(a!=0,mask):print(a)
